/**
 * team_* 工具参数 JSON Schema（手写字面量）。
 *
 * S1 结论：裸 ToolDefinition 不做参数校验，execute 内自行校验并抛可读错误；
 * 这里集中声明各工具的 wire schema，供 schema JSON 克隆规范化后呈现给模型。
 * 命名遵循 snake_case 参数惯例（omo team-mode / Claude Code Agent Teams 对照）。
 */

export const str = (description: string) => ({ type: "string", description });

export const optStr = (description: string) => ({
  type: "string",
  description: `${description} (optional)`,
});

export const num = (description: string) => ({ type: "number", description });

/** 布尔参数。 */
export const bool = (description: string) => ({ type: "boolean", description });

export const arrayOfStr = (description: string) => ({
  type: "array",
  items: { type: "string" },
  description,
});

export const schemas = {
  // team_init 已下线（#51）：实例化移至 HTTP 面 /api/xiaozhuge/team/create。
  spawn: {
    parameters: {
      type: "object",
      properties: {
        member: str("Logical member name (role id), e.g. 'coder'."),
        durable_id: str("Durable subagent id returned by the subagent tool."),
        role: str("Role id defined in the team template."),
        tier: { type: "number", description: "Hierarchy tier (0 = Tier-0 master)." },
        parent: optStr("Direct parent member name; omit for root members."),
      },
      required: ["member", "durable_id", "role", "tier"],
      additionalProperties: false,
    },
  },
  inbox: {
    parameters: {
      type: "object",
      properties: {
        member: str("Your member name."),
        envelope_id: optStr("Claim this specific envelope instead of listing unread."),
      },
      required: ["member"],
      additionalProperties: false,
    },
  },
  ack: {
    parameters: {
      type: "object",
      properties: {
        member: str("Your member name."),
        envelope_id: str("Envelope id being acknowledged."),
      },
      required: ["member", "envelope_id"],
      additionalProperties: false,
    },
  },
  send: {
    parameters: {
      type: "object",
      properties: {
        to: str("Recipient member name."),
        from: str("Sender member name (your own member name)."),
        type: str("Message type, e.g. 'task-done', 'blocked', 'info'."),
        body: { description: "Message payload (any JSON value)." },
      },
      required: ["to", "from", "type", "body"],
      additionalProperties: false,
    },
  },
  taskCreate: {
    parameters: {
      type: "object",
      properties: {
        title: str("Short task title."),
        room: str("Room the task belongs to."),
        assignee: optStr("Role assigned to execute the task."),
        touched_paths: arrayOfStr("Paths this task will touch (mutex assertion input)."),
        mutex_groups: arrayOfStr("Mutex group labels; running tasks sharing a group conflict."),
        max_rounds: num("Max patrol rounds for this task."),
        dod: arrayOfStr("DoD checklist items (judge verifies each)."),
        baseline: optStr("Baseline pointer (e.g. git ref) for redo reconciliation."),
      },
      required: ["title", "room"],
      additionalProperties: false,
    },
  },
  taskUpdate: {
    parameters: {
      type: "object",
      properties: {
        task_id: str("Task id returned by team_task_create."),
        status: {
          type: "string",
          enum: ["queued", "running", "blocked", "done", "cancelled"],
          description: "New status; must be a legal transition.",
        },
        assignee: optStr("New assignee role."),
        rounds: num("Current completed round count (monotonic)."),
        artifact: optStr("Artifact pointer once produced."),
        expect_rev: num("Optimistic concurrency: expected current rev."),
      },
      required: ["task_id"],
      additionalProperties: false,
    },
  },
  taskList: {
    parameters: {
      type: "object",
      properties: {
        room: optStr("Filter by room."),
        status: {
          type: "string",
          enum: ["queued", "running", "blocked", "done", "cancelled"],
          description: "Filter by status (optional).",
        },
      },
      additionalProperties: false,
    },
  },
  stateGet: {
    parameters: {
      type: "object",
      properties: {
        room: str("Room name."),
        role: optStr("Single role shard; omit to list all shards in the room."),
      },
      required: ["room"],
      additionalProperties: false,
    },
  },
  stateSet: {
    parameters: {
      type: "object",
      properties: {
        room: str("Room name."),
        role: str("Your member name (own your shard)."),
        status: {
          type: "string",
          enum: ["running", "blocked", "done"],
          description: "Reserved stage triplet.",
        },
        ext: { description: "Display-only business payload." },
      },
      required: ["room", "role", "status"],
      additionalProperties: false,
    },
  },
  handoff: {
    parameters: {
      type: "object",
      properties: {
        task_id: str("Task being handed off."),
        to_role: str("Receiving role."),
        receipt: arrayOfStr(
          "Judge mode only: per-DoD-item conclusions like 'pass: ...' / 'fail: ...'.",
        ),
      },
      required: ["task_id", "to_role"],
      additionalProperties: false,
    },
  },
} as const;

src/plugin/team-home.ts.source:
/**
 * 宿主绑定层：TEAM_HOME 解析（ADR 0005/#13 冻结口径）。
 *
 * runtime 纯库只认抽象根；这里把 `<主会话id>` 绑定到
 * `<DSH_HOME>/xiaozhuge/sessions/<主会话id>`，一个主会话 = 一个实例根，
 * 崩溃恢复可借 dsh transcript 回溯。
 *
 * 三级模板来源（ADR 0013）：
 * - user 层 = `<DSH_HOME>/xiaozhuge/templates/`（ADR 0002 定稿落点）
 * - project 层 = `<projectRoot>/.xiaozhuge/templates/`（ADR 0002 定稿落点）
 */
import { homedir } from "node:os";
import { join } from "node:path";

/** 解析 DSH_HOME（默认 ~/.dsh）。 */
export function resolveDshHome(): string {
  return process.env.DSH_HOME ?? join(homedir(), ".dsh");
}

/**
 * 解析某主会话的 TEAM_HOME 实例根。
 * @param sessionId 主会话 id（dsh session id）。
 */
export function resolveTeamHome(sessionId: string): string {
  return join(resolveDshHome(), "xiaozhuge", "sessions", sessionId);
}

/** user 层模板根（ADR 0013）：<DSH_HOME>/xiaozhuge/templates/。 */
export function userTemplatesRoot(): string {
  return join(resolveDshHome(), "xiaozhuge", "templates");
}

/** project 层模板根（ADR 0013）：<projectRoot>/.xiaozhuge/templates/。 */
export function projectTemplatesRoot(projectRoot: string): string {
  return join(projectRoot, ".xiaozhuge", "templates");
}

src/plugin/team-launch.ts.source:
/**
 * Team 拉起入口 HTTP 面（#51，ADR 0011；#51 修订：入口收敛进会话内）。
 *
 * 一键链路（浏览器端 client 插件在输入框内完成，不再打开独立页）：
 *   ① session.list 推导当前会话（blank 首轮判定 + cwd 工作区推导）
 *   → ② POST /api/xiaozhuge/team/create（本文件：服务端跑 init 持久化）
 *   → ③ POST /api/session.prompt 投递 tier0_prompt 首条消息
 *     （输入框草稿作为首条用户任务，空则只投递规程）。
 *
 * init 由此从 LLM 工具面移到 HTTP 面：team_init 工具下线，handler 逻辑
 * 保留复用。安全语义沿 Gate Console 先例：POST 同源 Origin + Fetch
 * Metadata 双头断言；scenario 运行时校验 builtin 白名单。
 *
 * 输入框内「创建团队」按钮与场景浮层由客户端插件（src/client/）经
 * conversation.input.right 官方插槽渲染（ADR 0014）。
 */
import { existsSync, readFileSync } from "node:fs";
import type { IncomingMessage, ServerResponse } from "node:http";
import { join } from "node:path";
import type { WebRoute } from "@deepseek-ai/dsh-host-webserver";
import { resolveTeamHome, userTemplatesRoot, projectTemplatesRoot } from "./team-home.js";
import { createHandlers, PACKAGE_ROOT } from "./handlers.js";
import { layout, listScenarios } from "../runtime/index.js";
import { fetchSiteAllowed, originAllowed } from "./gate-console.js";

/** 独立入口页路径（保留为兜底；client 插件不再跳转此页）。 */
export const ROUTES_LAUNCH = "/xiaozhuge/launch";

function writeJson(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { "content-type": "application/json; charset=utf-8" });
  res.end(JSON.stringify(body));
}

async function readBody(req: IncomingMessage): Promise<string> {
  let raw = "";
  for await (const chunk of req) raw += String(chunk);
  return raw;
}

/** 启动消息头（不含规程正文）；bootMessage 与页面脚本共用同一前缀。 */
export const BOOT_MESSAGE_HEAD =
  "团队已由人经入口创建，实例初始化完成。以下是你的 Tier-0 规程与场景编排" +
  "提示词全文（规程在前、场景段在后，以固定分隔符分界），请从启动对账节开始执行：";

/** 启动消息 = 前缀 + 组装好的 tier0_prompt。 */
export function bootMessage(tier0Prompt: string): string {
  return `${BOOT_MESSAGE_HEAD}\n\n${tier0Prompt}`;
}

/** Team 拉起入口路由组（scenarios/status/create API + 独立入口页）。 */
export function makeLaunchRoutes(): WebRoute[] {
  return [
    {
      kind: "exact",
      path: "/api/xiaozhuge/team/scenarios",
      handler: async (req, res) => {
        const url = new URL(req.url ?? "/", "http://localhost");
        const workspace = url.searchParams.get("workspace") || undefined;
        // 三级来源根组装（project 层可选，需 workspace 参数）
        const roots: Array<{ source: "builtin" | "user" | "project"; dir: string }> = [
          { source: "builtin", dir: join(PACKAGE_ROOT, "templates") },
          { source: "user", dir: userTemplatesRoot() },
        ];
        if (workspace) {
          roots.push({ source: "project", dir: projectTemplatesRoot(workspace) });
        }
        writeJson(res, 200, { scenarios: listScenarios(roots) });
      },
    },
    {
      kind: "exact",
      path: "/api/xiaozhuge/team/status",
      handler: async (req, res) => {
        const url = new URL(req.url ?? "/", "http://localhost");
        const sessionId = url.searchParams.get("session");
        if (!sessionId) {
          writeJson(res, 400, { error: "missing session parameter" });
          return;
        }
        const l = layout(resolveTeamHome(sessionId));
        // 团队会话判定：实例根已初始化（team.yaml 快照在场）。
        if (!existsSync(l.teamYaml)) {
          writeJson(res, 200, { is_team: false });
          return;
        }
        try {
          const snap = JSON.parse(readFileSync(l.teamYaml, "utf8")) as {
            name?: string;
            playbook_digest?: string;
          };
          writeJson(res, 200, {
            is_team: true,
            name: snap.name ?? null,
            playbook_digest: snap.playbook_digest ?? null,
          });
        } catch {
          writeJson(res, 200, { is_team: true, name: null, playbook_digest: null });
        }
      },
    },
    {
      kind: "exact",
      path: "/api/xiaozhuge/team/create",
      handler: async (req, res) => {
        if (req.method !== "POST") {
          writeJson(res, 405, { error: "method not allowed" });
          return;
        }
        // 安全最小集：与 Gate Console 同款双头断言（复用同一实现）。
        if (!originAllowed(req)) {
          writeJson(res, 403, { error: "forbidden: missing or cross-origin Origin header" });
          return;
        }
        if (!fetchSiteAllowed(req)) {
          writeJson(res, 403, { error: "forbidden: cross-site Sec-Fetch-Site" });
          return;
        }
        try {
          const body = JSON.parse(await readBody(req)) as {
            session?: string;
            scenario?: string;
            source?: string;
            workspace?: string;
            instance_note?: string;
          };
          if (typeof body.session !== "string" || body.session.length === 0) {
            writeJson(res, 400, { error: "session required" });
            return;
          }
          // handler 层负责 scenario 校验（unknown-scenario / ambiguous-scenario 稳定错误码）。
          const handlers = createHandlers(resolveTeamHome(body.session), body.session);
          const value = (await handlers.init({
            scenario: body.scenario,
            source: body.source,
            project_root: body.workspace,
            instance_note: body.instance_note,
          })) as Record<string, unknown>;
          writeJson(res, 200, value);
        } catch (error) {
          const e = error as { code?: string; message?: string };
          const status = e.code === "unknown-scenario" || e.code === "ambiguous-scenario" ? 400 : 409;
          writeJson(res, status, {
            error: { code: e.code ?? "internal-error", message: e.message ?? String(error) },
          });
        }
      },
    },
    {
      kind: "exact",
      path: ROUTES_LAUNCH,
      handler: async (_req, res) => {
        res.writeHead(200, { "content-type": "text/html; charset=utf-8" });
        res.end(launchPageHtml());
      },
    },
  ];
}

/** 独立入口页（内联 HTML；一键编排 workspace→session→init→prompt 四步）。 */
export function launchPageHtml(): string {
  const headLiteral = JSON.stringify(BOOT_MESSAGE_HEAD);
  return `<!doctype html>
<html lang="zh">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>小诸葛 · 创建团队</title>
<style>
  :root { color-scheme: light dark; }
  body { font-family: system-ui, sans-serif; margin: 0; padding: 16px; background: #f6f7f9; color: #1a1a1a; }
  @media (prefers-color-scheme: dark) { body { background: #14161a; color: #e8e8ea; } .card { background: #1e2128 !important; border-color: #33383f !important; } }
  h1 { font-size: 18px; margin: 8px 0 12px; }
  .card { border: 1px solid #ddd; border-radius: 10px; padding: 14px; background: #fff; max-width: 640px; margin-bottom: 12px; }
  label { display: block; font-size: 13px; margin: 10px 0 4px; }
  input, select { width: 100%; box-sizing: border-box; padding: 7px 9px; border: 1px solid #bbb; border-radius: 6px; background: inherit; color: inherit; font-size: 14px; }
  button { padding: 8px 18px; border-radius: 6px; border: none; cursor: pointer; font-size: 14px; background: #2da44e; color: #fff; margin-top: 12px; }
  button:disabled { opacity: .5; cursor: wait; }
  .hint { font-size: 12px; opacity: .65; margin-top: 6px; white-space: pre-wrap; }
  .err { color: #cf222e; font-size: 13px; margin-top: 8px; white-space: pre-wrap; }
</style>
</head>
<body>
<h1>创建团队</h1>
<div class="card">
  <label>工作区路径（宿主 workspace，绝对路径）</label>
  <input id="ws-path" placeholder="/path/to/workspace">
  <label>场景模板</label>
  <select id="scenario"></select>
  <label>备注（可选）</label>
  <input id="note" placeholder="instance note">
  <button id="go">一键建团并投递规程</button>
  <div class="err" id="err"></div>
  <div class="hint" id="log"></div>
</div>
<script>
const $ = (s) => document.querySelector(s);
const BOOT_HEAD = ${headLiteral};
const log = (m) => ($("#log").textContent += m + "\\n");
async function jfetch(method, path, body) {
  const r = await fetch(path, {
    method,
    headers: body !== undefined ? { "content-type": "application/json" } : {},
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const data = await r.json().catch(() => ({}));
  if (!r.ok && data.error) {
    throw new Error(typeof data.error === "object"
      ? (data.error.code + ": " + data.error.message)
      : String(data.error));
  }
  if (!r.ok) throw new Error("HTTP " + r.status);
  return data;
}
(async () => {
  const sel = $("#scenario");
  const list = (await jfetch("GET", "/api/xiaozhuge/team/scenarios")).scenarios;
  for (const s of list) {
    const o = document.createElement("option");
    o.value = s.name + "|" + s.source;
    o.textContent = s.name + " (" + s.source + ")";
    sel.appendChild(o);
  }
})();
$("#go").addEventListener("click", async () => {
  const btn = $("#go");
  btn.disabled = true;
  $("#err").textContent = "";
  $("#log").textContent = "";
  try {
    const wsPath = $("#ws-path").value.trim();
    if (!wsPath) throw new Error("请填写工作区路径");
    const ws = await jfetch("POST", "/api/workspace.create", { path: wsPath });
    log("workspace: " + ws.workspace.workspaceId);
    const sess = await jfetch("POST", "/api/session.create", {
      workspaceId: ws.workspace.workspaceId,
      agentPreset: "standard",
    });
    const sessionId = sess.sessionId;
    log("session: " + sessionId);
    const selVal = $("#scenario").value;
    const pipe = selVal.indexOf("|");
    const scenario = pipe >= 0 ? selVal.slice(0, pipe) : selVal;
    const source = pipe >= 0 ? selVal.slice(pipe + 1) : undefined;
    const created = await jfetch("POST", "/api/xiaozhuge/team/create", {
      session: sessionId,
      scenario: scenario,
      source: source,
      workspace: wsPath,
      instance_note: $("#note").value.trim() || null,
    });
    log("team initialized: " + created.home);
    await jfetch("POST", "/api/session.prompt", {
      sessionId,
      mode: "queue",
      content: [{ type: "text", text: BOOT_HEAD + "\\n\\n" + created.tier0_prompt }],
    });
    log("规程已投递。打开会话 " + sessionId + " 即可开始。");
  } catch (e) {
    $("#err").textContent = String(e.message ?? e);
  } finally {
    btn.disabled = false;
  }
});
</script>
</body>
</html>`;
}

src/runtime/collab/blackboard.ts.source:
/**
 * 黑板：rooms/<room>/state/<role>.json per-role 分片读写。
 * 保留态三元组（running/blocked/done）强制为 shard.status；业务子状态放
 * ext 字段仅展示。同 role 并发写属协议违规（单写者约定，与事件流一致）；
 * 跨 role 分片天然路径隔离。
 */
import { existsSync } from "node:fs";
import { readdir } from "node:fs/promises";
import { join } from "node:path";
import { roomLayout } from "../kernel/paths.js";
import { isReservedStage } from "../kernel/types.js";
import { readJson, writeJsonAtomic } from "../kernel/fs-utils.js";
import { RuntimeError } from "../kernel/errors.js";

/** 黑板分片：保留态 + 自由业务负载（ext 仅展示，不参与归约）。 */
export interface Shard {
  role: string;
  status: string;
  /** 业务子状态/任意展示性负载。 */
  ext?: unknown;
  updatedAt: number;
}

/**
 * 写入角色分片。status 必须是保留态三元组之一——黑板是巡场归约的数据源，
 * 非法值会让「阻塞高亮/闭环判定」失去意义，直接拒绝。
 */
export async function setShard(
  teamHome: string,
  room: string,
  role: string,
  shard: Omit<Shard, "role" | "updatedAt"> & { ext?: unknown },
): Promise<Shard> {
  if (!isReservedStage(shard.status)) {
    throw new RuntimeError(
      "invalid-stage",
      `blackboard status must be one of running|blocked|done, got: ${shard.status}`,
    );
  }
  const full: Shard = { ...shard, role, status: shard.status, updatedAt: Date.now() };
  await writeJsonAtomic(join(roomLayout(teamHome, room).stateDir, `${role}.json`), full);
  return full;
}

/** 读角色分片；不存在返回 undefined。 */
export async function getShard(
  teamHome: string,
  room: string,
  role: string,
): Promise<Shard | undefined> {
  return readJson<Shard>(join(roomLayout(teamHome, room).stateDir, `${role}.json`));
}

/** 列出房间全部分片。 */
export async function listShards(teamHome: string, room: string): Promise<Shard[]> {
  const stateDir = roomLayout(teamHome, room).stateDir;
  if (!existsSync(stateDir)) return [];
  const shards: Shard[] = [];
  for (const entry of await readdir(stateDir)) {
    if (!entry.endsWith(".json")) continue;
    const shard = await readJson<Shard>(join(stateDir, entry));
    if (shard) shards.push(shard);
  }
  return shards.sort((a, b) => a.role.localeCompare(b.role));
}

src/runtime/collab/mailbox.ts.source:
/**
 * 信箱三段式投递协议（v2.2 定稿 §3 mailbox，omo 模式）。
 *
 * 三段：<member>/<uuid>.json（待读）→ .delivering-<uuid>.json（消费者 claim 态）
 * → processed/<uuid>.json（已确认）。
 *
 * 语义钉死（对抗评审 M1/M2）：
 * - `.delivering-` 前缀单义化为「消费者 claim 态」；发送方暂存走原子写临时
 *   文件生态（.tmp-），不占用 delivering 位。
 * - 发布/claim 均用 linkNoReplace（create-if-not-exists）：待读位已存在 =
 *   double-inject；delivering 已存在 = 已被认领或残片冲突——绝不用裸 rename
 *   （静默覆盖）。
 * - at-least-once：claim 态超 TTL 会被收割重投，消费者必须按信封 id 幂等处理。
 */
import { readdir, rm } from "node:fs/promises";
import { existsSync } from "node:fs";
import { join } from "node:path";
import { linkNoReplace, readJson, TMP_PREFIX, writeJsonAtomic } from "../kernel/fs-utils.js";
import { memberMailboxDir } from "../kernel/paths.js";
import { recoverDeliveries } from "../kernel/recovery.js";

export const DELIVERING_PREFIX = ".delivering-";
export const PROCESSED_DIR = "processed";

/** 信封：信箱文件的协议内容。 */
export interface Envelope {
  id: string;
  from: string;
  to: string;
  type: string;
  body: unknown;
  createdAt: number;
}

function unreadFile(memberDir: string, uuid: string): string {
  return join(memberDir, `${uuid}.json`);
}

function deliveringFile(memberDir: string, uuid: string): string {
  return join(memberDir, `${DELIVERING_PREFIX}${uuid}.json`);
}

function processedFile(memberDir: string, uuid: string): string {
  return join(memberDir, PROCESSED_DIR, `${uuid}.json`);
}

/**
 * 投递一条消息到成员待读位。
 * @returns 信封 id（= uuid）。
 * @throws Error 目标已存在（double-inject）。
 */
export async function deliver(
  teamHome: string,
  to: string,
  message: { from: string; type: string; body: unknown },
  opts: { id?: string } = {},
): Promise<string> {
  const memberDir = memberMailboxDir(teamHome, to);
  const id = opts.id ?? crypto.randomUUID();
  const envelope: Envelope = {
    id,
    from: message.from,
    to,
    type: message.type,
    body: message.body,
    createdAt: Date.now(),
  };
  // 发送方暂存（.tmp- 生态、隐藏名不进待读枚举）→ link 原子发布 → 清暂存。
  const staged = join(memberDir, `${TMP_PREFIX}outgoing-${id}.json`);
  await writeJsonAtomic(staged, envelope);
  const published = await linkNoReplace(staged, unreadFile(memberDir, id));
  if (!published) {
    await rm(staged);
    throw new Error(`double-inject: envelope ${id} already in ${to}'s mailbox`);
  }
  await rm(staged);
  return id;
}

/** 列出成员待读信封。 */
export async function readUnread(teamHome: string, member: string): Promise<Envelope[]> {
  const memberDir = memberMailboxDir(teamHome, member);
  if (!existsSync(memberDir)) return [];
  const out: Envelope[] = [];
  for (const entry of await readdir(memberDir)) {
    if (!entry.endsWith(".json") || entry.startsWith(".")) continue;
    const env = await readJson<Envelope>(join(memberDir, entry));
    if (env) out.push(env);
  }
  return out.sort((a, b) => a.createdAt - b.createdAt);
}

/**
 * 认领一条待读消息：待读位 → delivering（link + unlink，防双活消费）。
 * @throws Error 待读位不存在或已被认领。
 */
export async function claim(teamHome: string, member: string, uuid: string): Promise<Envelope> {
  const memberDir = memberMailboxDir(teamHome, member);
  if (!existsSync(unreadFile(memberDir, uuid))) {
    throw new Error(`unknown envelope ${uuid} in ${member}'s unread segment`);
  }
  const claimed = await linkNoReplace(unreadFile(memberDir, uuid), deliveringFile(memberDir, uuid));
  if (!claimed) {
    throw new Error(`envelope ${uuid} is already claimed or in conflict`);
  }
  await rm(unreadFile(memberDir, uuid));
  return (await readJson<Envelope>(deliveringFile(memberDir, uuid)))!;
}

/**
 * 确认完成：delivering → processed。重复 ack 幂等成功（processed 已存在时
 * 直接清残片返回既有结果语义）。
 */
export async function acknowledge(teamHome: string, member: string, uuid: string): Promise<void> {
  const memberDir = memberMailboxDir(teamHome, member);
  const processing = deliveringFile(memberDir, uuid);
  if (!existsSync(processing)) return; // 幂等：无在途残片
  await import("node:fs/promises").then((m) => m.mkdir(join(memberDir, PROCESSED_DIR), { recursive: true }));
  const ok = await linkNoReplace(processing, processedFile(memberDir, uuid));
  await rm(processing);
  void ok; // false = processed 已有同 id：重复 ack，丢弃本次即可
}

/** 成员信箱收割：先清 processed 命中的 claim 残片，其余交给 P2a TTL 收割。 */
export async function harvestMailbox(
  teamHome: string,
  member: string,
  ttlMs?: number,
): Promise<number> {
  const memberDir = memberMailboxDir(teamHome, member);
  let swept = 0;
  if (existsSync(memberDir)) {
    for (const entry of await readdir(memberDir)) {
      if (!entry.startsWith(DELIVERING_PREFIX) || !entry.endsWith(".json")) continue;
      const uuid = entry.slice(DELIVERING_PREFIX.length, -".json".length);
      if (existsSync(processedFile(memberDir, uuid))) {
        await rm(join(memberDir, entry));
        swept += 1;
      }
    }
  }
  const recovered = await recoverDeliveries(join(teamHome, "mailbox"), ttlMs);
  return swept + recovered.length;
}

src/runtime/kernel/cas-lock.ts.source:
/**
 * CAS 锁薄适配层（v2.2 定稿 §5；#29 第 C 项：proper-lockfile@4.1.2）。
 *
 * 资源语义：acquireCas/releaseCas/withCasLock/peekLock 的首参为**资源基路径**
 * （不含 .lock 后缀），库以 `${resource}.lock` **目录**（mkdir 原子，跨平台）
 * 为锁形态——rc 前无兼容包袱，直接切换到正确形态。
 *
 * 适配层自管语义（库不提供）：
 * - instance-id 幂等重入：锁目录内 owner.json 记录持有者，acquire 前读比对，
 *   同 id → reentered（P4 场景脚本依赖该判定）；
 * - 孤儿锁保守策略：锁目录存在但无有效 owner（mkdir 与 owner 写入之间崩溃
 *   的产物）默认拒绝，仅显式 takeoverOrphan 时清除接管——**不启用库的
 *   mtime 自动过期抢夺**（其 stale 最小 2000ms 且活锁会被自动 steal，违反
 *   「接管是显式决策」定稿口径）；owner 完好但进程已死的残留同样按冲突拒绝，
 *   死锁恢复仍归巡场对账职责。
 *
 * 库承担：跨平台原子获取/释放、持锁期 mtime 续期与 compromise 检测、
 * signal-exit 进程退出清理。
 */
import { existsSync } from "node:fs";
import { readFile, rm, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { lock as plLock, unlock as plUnlock } from "proper-lockfile";
import { LockError } from "./errors.js";
import type { LockInfo } from "./types.js";

/** 锁目录内持有者记录文件名。 */
const OWNER_FILE = "owner.json";

/**
 * 库侧 staleness 参数：适配层不消费 mtime 判定，仅取足够大值避免库的
 * 自动 steal 干扰保守策略；update 续期为 unref 定时器，不阻退出。
 */
const PL_OPTIONS = {
  stale: 24 * 60 * 60 * 1000,
  // 资源基路径是协议约定的名义路径（文件本身不必存在），跳过 realpath 解析。
  realpath: false,
  onCompromised: () => {},
} as const;

function lockDirOf(resourcePath: string): string {
  return `${resourcePath}.lock`;
}

async function readOwner(lockDir: string): Promise<LockInfo | undefined> {
  if (!existsSync(lockDir)) return undefined;
  let raw: string;
  try {
    raw = await readFile(join(lockDir, OWNER_FILE), "utf8");
  } catch {
    return undefined;
  }
  try {
    const parsed = JSON.parse(raw) as Partial<LockInfo>;
    if (typeof parsed.holder !== "string") return undefined;
    return { holder: parsed.holder, acquiredAt: parsed.acquiredAt ?? 0 };
  } catch {
    return undefined;
  }
}

export type AcquireResult = "acquired" | "reentered";

/**
 * 原子获取 CAS 锁。
 * @param resourcePath 资源基路径（如 `<TEAM_HOME>/room`），锁形态为
 *   `${resourcePath}.lock` 目录。
 * @param instanceId 持有者幂等键（约定为主会话 id，跨重启稳定）。
 * @param opts.takeoverOrphan 锁目录存在但无有效 owner（孤儿）时强制清除接管。
 * @throws LockConflictError 已被其他实例持有（含 owner 完好的死进程残留）；
 *   LockError("orphan-lock") 孤儿锁未授权接管。
 */
export async function acquireCas(
  resourcePath: string,
  instanceId: string,
  opts: { takeoverOrphan?: boolean } = {},
): Promise<AcquireResult> {
  const lockDir = lockDirOf(resourcePath);
  if (existsSync(lockDir)) {
    let owner = await readOwner(lockDir);
    if (owner === undefined) {
      // mkdir 与 owner 写入之间的启动竞态窗口：短暂轮询等待持有者落位，
      // 仍无有效 owner 才判孤儿（崩溃残留是持久的，不会在轮询内消失）。
      for (let i = 0; i < 10 && owner === undefined; i += 1) {
        await new Promise((r) => setTimeout(r, 20));
        owner = await readOwner(lockDir);
      }
    }
    if (owner === undefined) {
      if (!opts.takeoverOrphan) {
        throw new LockError(
          "orphan-lock",
          `orphan lock at ${lockDir} (no valid owner); retry with takeoverOrphan to take over`,
        );
      }
      // 显式接管：清除无主锁目录后走正常获取。
      await rm(lockDir, { recursive: true, force: true });
    } else if (owner.holder !== instanceId) {
      throw new LockConflictError(lockDir, owner.holder);
    } else {
      return "reentered";
    }
  }

  try {
    await plLock(resourcePath, PL_OPTIONS);
  } catch {
    // ELOCKED：竞态窗口内被抢先。owner 可能尚未落位，holder 仅作诊断展示。
    const owner = await readOwner(lockDir);
    throw new LockConflictError(lockDir, owner?.holder ?? "(acquiring)");
  }
  await writeOwner(lockDir, instanceId);
  return "acquired";
}

async function writeOwner(lockDir: string, instanceId: string): Promise<void> {
  await writeFile(join(lockDir, OWNER_FILE), JSON.stringify({ holder: instanceId, acquiredAt: Date.now() }), "utf8");
}

/**
 * 释放锁：校验 owner 后删除。孤儿锁（无有效 owner）视为已释放并幂等清除；
 * 非持有者拒绝；锁不存在静默成功。
 * @throws LockConflictError 非持有者。
 */
export async function releaseCas(resourcePath: string, instanceId: string): Promise<void> {
  const lockDir = lockDirOf(resourcePath);
  if (!existsSync(lockDir)) return;
  const owner = await readOwner(lockDir);
  if (owner === undefined) {
    await rm(lockDir, { recursive: true, force: true });
    return;
  }
  if (owner.holder !== instanceId) {
    throw new LockConflictError(lockDir, owner.holder);
  }
  await rm(join(lockDir, OWNER_FILE), { force: true });
  try {
    await plUnlock(resourcePath);
  } catch {
    // unlock 失败（如目录已被动过）：兜底强清，保证释放语义收敛。
    await rm(lockDir, { recursive: true, force: true });
  }
}

/** 持锁执行 fn，结束（含异常）后释放。 */
export async function withCasLock<T>(
  resourcePath: string,
  instanceId: string,
  fn: () => Promise<T>,
): Promise<T> {
  await acquireCas(resourcePath, instanceId);
  try {
    return await fn();
  } finally {
    await releaseCas(resourcePath, instanceId);
  }
}

/** 读当前锁信息（诊断用）。 */
export async function peekLock(resourcePath: string): Promise<LockInfo | undefined> {
  return readOwner(lockDirOf(resourcePath));
}

export class LockConflictError extends LockError {
  constructor(lockPath: string, holder: string) {
    super("lock-conflict", `lock ${lockPath} is held by another instance: ${holder}`);
  }
}

