/**
 * append-only 事件流（rooms/<room>/events.jsonl，仅运行时单写者）。
 *
 * 单写者约定：同一房间同时只允许一个运行时实例写入（多 room 并行写各自
 * events.jsonl 允许）；双实例并发写同 room 属协议违规，本层不做跨进程仲裁。
 *
 * 崩溃容错：append 半途 kill 会留下截断尾行——初始化扫描与回放读取均跳过
 * 末尾坏行并如实报告（tornTail），不因坏行抛错。
 */
import { existsSync } from "node:fs";
import { readFile, stat, writeFile } from "node:fs/promises";
import type { EventRecord } from "./types.js";

export interface AppendInput {
  session_id: string;
  actor: string;
  type: string;
  payload?: unknown;
}

export interface ReadResult {
  events: EventRecord[];
  /** 解析失败的行号列表（1-based 数据行）。 */
  corruptLines: number[];
}

/** 单写者互斥文件：同 room 的 writer 锁名。 */
export const WRITER_LOCK_SUFFIX = ".writer";

export class EventLog {
  private readonly file: string;
  private nextSeq = 1;
  private tornTail = false;

  constructor(file: string) {
    this.file = file;
  }

  /**
   * 扫描现有事件恢复 seq 游标；末尾截断坏行不抛错，标记 tornTail。
   * 必须在首次 append 前调用。
   */
  async init(): Promise<void> {
    if (!existsSync(this.file)) {
      this.nextSeq = 1;
      this.tornTail = false;
      return;
    }
    const raw = await readFile(this.file, "utf8");
    let max = 0;
    let torn = false;
    const lines = raw.split("\n").filter((l) => l !== "");
    for (let i = 0; i < lines.length; i++) {
      try {
        const rec = JSON.parse(lines[i]!) as EventRecord;
        if (typeof rec.seq === "number" && rec.seq > max) max = rec.seq;
      } catch {
        // 仅末尾坏行视为 torn tail；中间坏行同样跳过但一并标记。
        torn = true;
        void i;
      }
    }
    this.nextSeq = max + 1;
    this.tornTail = torn;
  }

  /** 初始化时是否发现解析失败行。 */
  hasTornTail(): boolean {
    return this.tornTail;
  }

  /** 追加一条事件（副作用记账唯一入口）；返回带 seq 的完整记录。 */
  async append(input: AppendInput): Promise<EventRecord> {
    const record: EventRecord = {
      seq: this.nextSeq++,
      ts: Date.now(),
      session_id: input.session_id,
      actor: input.actor,
      type: input.type,
      payload: input.payload ?? null,
    };
    await writeFile(this.file, JSON.stringify(record) + "\n", { flag: "a", encoding: "utf8" });
    return record;
  }

  /**
   * 回放读取（fromSeq 起全量）。坏行跳过并计入 corruptLines；
   * 空文件返回空数组。
   */
  async read(fromSeq = 1): Promise<ReadResult> {
    if (!existsSync(this.file)) return { events: [], corruptLines: [] };
    const raw = await readFile(this.file, "utf8");
    const events: EventRecord[] = [];
    const corruptLines: number[] = [];
    const lines = raw.split("\n");
    for (let i = 0; i < lines.length; i++) {
      const line = lines[i]!;
      if (line === "") continue;
      try {
        const rec = JSON.parse(line) as EventRecord;
        if (rec.seq >= fromSeq) events.push(rec);
      } catch {
        corruptLines.push(i + 1);
      }
    }
    return { events, corruptLines };
  }

  /** 当前已用事件数（诊断/对账用）。 */
  async count(): Promise<number> {
    if (!existsSync(this.file)) return 0;
    const { size } = await stat(this.file);
    return size === 0 ? 0 : this.read().then((r) => r.events.length);
  }
}

src/runtime/kernel/fs-utils.ts.source:
/**
 * 原子文件原语（#29 第 A 项：write-file-atomic@8.0.0）。
 *
 * 跨平台原子写交给 npm 自身生产验证的实现（Windows rename EPERM 规避、
 * chmod/chown 复制、fsync）；崩溃残片两类：本仓 `.tmp-` 前缀与库的
 * `<target>.<digest>` 形态，由 {@link sweepTmp} 统一清扫。
 * 掉电级持久性（父目录 fsync）仍属过度设计，不在此层。
 */
import { link, mkdir, readdir, readFile, rm, stat } from "node:fs/promises";
import { existsSync } from "node:fs";
import writeFileAtomic from "write-file-atomic";
import { join, dirname } from "node:path";

/** 临时文件前缀；目录枚举时须过滤，recovery 负责清扫。 */
export const TMP_PREFIX = ".tmp-";

/**
 * write-file-atomic 崩溃残片判定：目标均为 *.json，残片形如
 * `<target>.<digest>`（含 ".json." 且不再以 .json 结尾）。
 * 协议内无合法文件名命中此形态（信箱暂存名以 .json 结尾，不受影响）。
 */
const LIB_TMP_RESIDUE = (entry: string): boolean => entry.includes(".json.") && !entry.endsWith(".json");

/** 确保目录存在（递归）。 */
export async function ensureDir(dir: string): Promise<void> {
  await mkdir(dir, { recursive: true });
}

/**
 * 原子写 JSON：write-file-atomic 同目录临时文件 + rename 到位。
 * 崩溃只可能残留临时文件（不影响读者），由 {@link sweepTmp} 清扫。
 */
export async function writeJsonAtomic(file: string, value: unknown): Promise<void> {
  await ensureDir(dirname(file));
  await writeFileAtomic(file, JSON.stringify(value, null, 2), "utf8");
}

/** 读 JSON 文件；不存在时返回 undefined。 */
export async function readJson<T>(file: string): Promise<T | undefined> {
  if (!existsSync(file)) return undefined;
  return JSON.parse(await readFile(file, "utf8")) as T;
}

/**
 * 清扫目录内的原子写临时残片（一级）：`.tmp-` 前缀与 write-file-atomic
 * `<target>.<digest>` 形态。
 * @returns 清除的文件数。
 */
export async function sweepTmp(dir: string): Promise<number> {
  if (!existsSync(dir)) return 0;
  let swept = 0;
  for (const entry of await readdir(dir)) {
    if (!entry.startsWith(TMP_PREFIX) && !LIB_TMP_RESIDUE(entry)) continue;
    const full = join(dir, entry);
    const s = await stat(full);
    if (s.isFile()) {
      await rm(full);
      swept += 1;
    }
  }
  return swept;
}

/**
 * 归档落点限位判定：target 必须落在 root 内（防越界写入）。
 * @returns 解析后的绝对目标路径。
 */
export function confineToRoot(root: string, target: string): string {
  const resolvedRoot = root.startsWith("/") ? root : join(process.cwd(), root);
  const resolvedTarget = target.startsWith("/") ? target : join(resolvedRoot, target);
  if (!resolvedTarget.startsWith(resolvedRoot.endsWith("/") ? resolvedRoot : resolvedRoot + "/")) {
    throw new Error(`archive target escapes TEAM_HOME: ${target}`);
  }
  return resolvedTarget;
}

/**
 * 原子 create-if-not-exists 复制引用：target 已存在时抛 EEXIST（不覆盖）。
 * Node 无 RENAME_NOREPLACE；防覆盖发布只能用 link。
 * @returns true = 本次创建；false = target 已存在（调用方决定残片处理）。
 */
export async function linkNoReplace(src: string, target: string): Promise<boolean> {
  try {
    await link(src, target);
    return true;
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "EEXIST") return false;
    throw error;
  }
}

src/runtime/kernel/gates.ts.source:
/**
 * gates/<id>.json 读写：pending → approved/denied 单向（Console 唯一写点的
 * 协议面；本层只提供原语，HTTP 路由属 P5 宿主层）。
 */
import { readdir, readFile } from "node:fs/promises";
import { join } from "node:path";
import type { GateRecord, GateStatus } from "./types.js";
import { GateError } from "./errors.js";
import { readJson, writeJsonAtomic } from "./fs-utils.js";

export interface NewGate {
  id: string;
  reason: string;
  requestedBy: string;
}

/** 打开闸口（status=pending）；同 id 已存在即拒（幂等键 = gate id）。 */
export async function openGate(gatesDir: string, input: NewGate): Promise<GateRecord> {
  const file = join(gatesDir, `${input.id}.json`);
  const existing = await readJson<GateRecord>(file);
  if (existing !== undefined) {
    throw new GateError("gate-exists", `gate ${input.id} already exists (${existing.status})`);
  }
  const record: GateRecord = {
    id: input.id,
    status: "pending",
    reason: input.reason,
    requestedBy: input.requestedBy,
    requestedAt: Date.now(),
  };
  await writeJsonAtomic(file, record);
  return record;
}

/** 读单个 gate；不存在返回 undefined。 */
export async function readGate(gatesDir: string, id: string): Promise<GateRecord | undefined> {
  return readJson<GateRecord>(join(gatesDir, `${id}.json`));
}

/**
 * 裁决：pending → approved/denied 单向；非 pending 即拒（不可逆，无重开）。
 * @param by 裁决主体（Console 审计字段）。
 */
export async function resolveGate(
  gatesDir: string,
  id: string,
  decision: Exclude<GateStatus, "pending">,
  by: string,
): Promise<GateRecord> {
  const file = join(gatesDir, `${id}.json`);
  const current = await readJson<GateRecord>(file);
  if (current === undefined) {
    throw new GateError("gate-not-found", `gate ${id} does not exist`);
  }
  if (current.status !== "pending") {
    throw new GateError("gate-resolved", `gate ${id} already resolved to ${current.status}`);
  }
  const next: GateRecord = {
    ...current,
    status: decision,
    ...(decision === "approved" || decision === "denied"
      ? { resolvedBy: by, resolvedAt: Date.now() }
      : {}),
  };
  await writeJsonAtomic(file, next);
  return next;
}

/** 枚举全部 gate（跳过损坏文件并如实报告）。 */
export async function listGates(
  gatesDir: string,
): Promise<{ gates: GateRecord[]; corrupt: string[] }> {
  let entries: string[];
  try {
    entries = await readdir(gatesDir);
  } catch {
    return { gates: [], corrupt: [] };
  }
  const gates: GateRecord[] = [];
  const corrupt: string[] = [];
  for (const entry of entries) {
    if (!entry.endsWith(".json")) continue;
    try {
      const rec = JSON.parse(await readFile(join(gatesDir, entry), "utf8")) as unknown;
      if (isGateRecord(rec)) gates.push(rec);
      else corrupt.push(entry);
    } catch {
      corrupt.push(entry);
    }
  }
  return { gates, corrupt };
}

function isGateRecord(value: unknown): value is GateRecord {
  const v = value as GateRecord;
  return (
    typeof v === "object" &&
    v !== null &&
    typeof v.id === "string" &&
    (["pending", "approved", "denied"] as const).includes(v.status)
  );
}

src/runtime/kernel/ledger.ts.source:
/**
 * 共享任务账本：每任务单文件原子写 + 状态机合法迁移强制（v2.2 定稿 §5）。
 * touched paths / mutexGroups 的分组互斥判定原语供工具层（P3）装配。
 */
import { randomUUID } from "node:crypto";
import { existsSync } from "node:fs";
import { mkdir, readdir, readFile } from "node:fs/promises";
import { join } from "node:path";
import { canTransition, type TaskRecord, type TaskStatus } from "./types.js";
import { LedgerError } from "./errors.js";
import { readJson, sweepTmp, writeJsonAtomic } from "./fs-utils.js";

/** 创建任务时的输入（id/rev/时间戳由账本生成）。 */
export interface NewTask {
  title: string;
  room: string;
  assignee?: string;
  touched?: string[];
  mutexGroups?: string[];
  maxRounds?: number;
  dod?: string[];
  baseline?: string;
}

/** 更新任务时的补丁：status 走状态机校验；其余字段浅覆盖。 */
export interface TaskPatch {
  title?: string;
  status?: TaskStatus;
  assignee?: string;
  touched?: string[];
  mutexGroups?: string[];
  rounds?: number;
  maxRounds?: number;
  dod?: string[];
  baseline?: string;
  artifact?: string;
}

export interface UpdateOptions {
  /** 乐观并发：期望的当前 rev，不匹配即拒绝（P3「读-判-写」原子性钩子）。 */
  expectRev?: number;
}

export class Ledger {
  private readonly tasksDir: string;

  constructor(teamHome: string, tasksDir: string) {
    this.tasksDir = tasksDir ?? join(teamHome, "ledger", "tasks");
  }

  /** 创建任务，返回初始记录（status=queued, rev=1）。 */
  async create(input: NewTask): Promise<TaskRecord> {
    const now = Date.now();
    const record: TaskRecord = {
      id: `task-${randomUUID()}`,
      title: input.title,
      status: "queued",
      room: input.room,
      ...(input.assignee !== undefined ? { assignee: input.assignee } : {}),
      touched: input.touched ?? [],
      mutexGroups: input.mutexGroups ?? [],
      rounds: 0,
      maxRounds: input.maxRounds ?? 0,
      dod: input.dod ?? [],
      ...(input.baseline !== undefined ? { baseline: input.baseline } : {}),
      rev: 1,
      createdAt: now,
      updatedAt: now,
    };
    await writeJsonAtomic(this.taskFile(record.id), record);
    return record;
  }

  /** 读单个任务；不存在返回 undefined。 */
  async get(id: string): Promise<TaskRecord | undefined> {
    return readJson<TaskRecord>(this.taskFile(id));
  }

  /**
   * 状态机受控更新。status 迁移非法即拒；expectRev 不匹配即拒；
   * rounds 只能单调递增。成功后 rev+1 并原子落盘。
   */
  async update(id: string, patch: TaskPatch, opts: UpdateOptions = {}): Promise<TaskRecord> {
    const current = await this.get(id);
    if (current === undefined) {
      throw new LedgerError("task-not-found", `task ${id} does not exist`);
    }
    if (opts.expectRev !== undefined && opts.expectRev !== current.rev) {
      throw new LedgerError(
        "rev-conflict",
        `task ${id} rev mismatch: expected ${opts.expectRev}, current ${current.rev}`,
      );
    }
    if (patch.status !== undefined && !canTransition(current.status, patch.status)) {
      throw new LedgerError(
        "illegal-transition",
        `task ${id}: illegal transition ${current.status} -> ${patch.status}`,
      );
    }
    if (patch.rounds !== undefined && patch.rounds < current.rounds) {
      throw new LedgerError("rounds-regress", `task ${id}: rounds cannot decrease`);
    }
    const next: TaskRecord = {
      ...current,
      ...patch,
      rev: current.rev + 1,
      updatedAt: Date.now(),
    };
    if (patch.rounds !== undefined && next.maxRounds > 0 && next.rounds > next.maxRounds) {
      throw new LedgerError(
        "rounds-exceeded",
        `task ${id}: rounds ${next.rounds} exceeds max ${next.maxRounds}`,
      );
    }
    await writeJsonAtomic(this.taskFile(id), next);
    return next;
  }

  /** 列出全部任务（跳过临时残片与损坏文件——损坏文件名会出现在结果 warnings）。 */
  async list(): Promise<{ tasks: TaskRecord[]; corrupt: string[] }> {
    if (!existsSync(this.tasksDir)) {
      await mkdir(this.tasksDir, { recursive: true });
    }
    const entries = await readdir(this.tasksDir);
    const tasks: TaskRecord[] = [];
    const corrupt: string[] = [];
    for (const entry of entries) {
      if (!entry.endsWith(".json")) continue;
      try {
        const raw = JSON.parse(await readFile(join(this.tasksDir, entry), "utf8")) as unknown;
        if (raw === undefined || typeof raw !== "object" || typeof (raw as TaskRecord).id !== "string") {
          corrupt.push(entry);
          continue;
        }
        tasks.push(raw as TaskRecord);
      } catch {
        corrupt.push(entry);
      }
    }
    return { tasks, corrupt };
  }

  private taskFile(id: string): string {
    return join(this.tasksDir, `${id}.json`);
  }

  /** 清扫本目录内的临时残片，返回清除数。 */
  async sweepTmpFiles(): Promise<number> {
    return sweepTmp(this.tasksDir);
  }
}


/**
 * 分组互斥断言原语：同房间 running 任务间，共享任一 mutexGroup 或
 * touched 字面交集非空即冲突（定稿 §6.1「同组互斥才允许 active」）。
 * @returns 冲突对清单；空数组 = 无冲突。
 */
export function findConflicts(
  tasks: TaskRecord[],
): Array<{ a: string; b: string; reason: string }> {
  const active = tasks.filter((t) => t.status === "running");
  const conflicts: Array<{ a: string; b: string; reason: string }> = [];
  for (let i = 0; i < active.length; i++) {
    for (let j = i + 1; j < active.length; j++) {
      const a = active[i]!;
      const b = active[j]!;
      if (a.room !== b.room) continue;
      const sharedGroup = a.mutexGroups.find((g) => b.mutexGroups.includes(g));
      if (sharedGroup !== undefined) {
        conflicts.push({ a: a.id, b: b.id, reason: `shared mutex group: ${sharedGroup}` });
        continue;
      }
      const overlap = a.touched.find((p) => b.touched.includes(p));
      if (overlap !== undefined) {
        conflicts.push({ a: a.id, b: b.id, reason: `touched path overlap: ${overlap}` });
      }
    }
  }
  return conflicts;
}

src/runtime/kernel/paths.ts.source:
/**
 * 目录协议路径解析（v2.2 定稿 §3 布局）。
 *
 * teamHome 即实例根：ADR 0005（#13 冻结口径）下由宿主绑定层解析为
 * `<DSH_HOME>/xiaozhuge/sessions/<主会话id>`，本库不关心其绝对形态，
 * 只按协议拼出各文件/目录的落点。
 */
import { join } from "node:path";

export interface RoomLayout {
  dir: string;
  /** append-only 事件流（仅运行时单写者）。 */
  eventsFile: string;
  /** 黑板 per-role 分片目录。 */
  stateDir: string;
  /** 简报目录。 */
  briefDir: string;
}

export interface Layout {
  teamHome: string;
  teamYaml: string;
  agentsJson: string;
  /** CAS 锁资源基路径（不含 .lock 后缀）；锁形态为 room.lock 目录（proper-lockfile）。 */
  roomLock: string;
  ledgerTasksDir: string;
  roomsDir: string;
  mailboxDir: string;
  gatesDir: string;
  archiveDir: string;
}

/** 解析实例根下的顶层协议路径。teamHome 即实例根，不再追加 <instance-id> 层。 */
export function layout(teamHome: string): Layout {
  return {
    teamHome,
    teamYaml: join(teamHome, "team.yaml"),
    agentsJson: join(teamHome, "agents.json"),
    roomLock: join(teamHome, "room"),
    ledgerTasksDir: join(teamHome, "ledger", "tasks"),
    roomsDir: join(teamHome, "rooms"),
    mailboxDir: join(teamHome, "mailbox"),
    gatesDir: join(teamHome, "gates"),
    archiveDir: join(teamHome, "archive"),
  };
}

/** 解析单个房间的布局。 */
export function roomLayout(teamHome: string, room: string): RoomLayout {
  const dir = join(layout(teamHome).roomsDir, room);
  return {
    dir,
    eventsFile: join(dir, "events.jsonl"),
    stateDir: join(dir, "state"),
    briefDir: join(dir, "brief"),
  };
}

/** 信箱成员目录。 */
export function memberMailboxDir(teamHome: string, member: string): string {
  return join(layout(teamHome).mailboxDir, member);
}

src/runtime/kernel/recovery.ts.source:
/**
 * 崩溃恢复原语（v2.2 定稿 §5 幂等与恢复表）：
 * - 信箱 .delivering-* TTL 收割（omo 模式，P2b 三段式的恢复半边）；
 * - 黑板 running 哨兵整分片作废重做；
 * - 原子写临时残片清扫。
 * 收割/作废结果以清单返回，审计事件由调用方追加到事件流。
 */
import { existsSync } from "node:fs";
import { link, readdir, rm, stat } from "node:fs/promises";
import { join } from "node:path";
import { TMP_PREFIX, readJson } from "./fs-utils.js";
import type { MemberRecord } from "./types.js";

/** 默认投递中 TTL：10 分钟（巡场轮次为分钟级节奏，够宽也够收）。 */
export const DEFAULT_DELIVERING_TTL_MS = 10 * 60_000;

export interface DeliveryRecovery {
  member: string;
  uuid: string;
  /** requeued = 回待读位；dropped = 待读位已存在（processed 防线命中），残片丢弃。 */
  action: "requeued" | "dropped";
}

/**
 * 收割超时的 .delivering-<uuid>.json 残片。
 * 直接 rename 回待读位；目标已存在（EEXIST）即丢弃残片——不做 stat-then-rename
 * （TOCTOU）。已确认过的 uuid 在 processed 位时其待读位不应存在；若存在说明
 * 确认前崩溃，回待读位是正确重投。
 */
export async function recoverDeliveries(
  mailboxDir: string,
  ttlMs = DEFAULT_DELIVERING_TTL_MS,
  now = Date.now(),
): Promise<DeliveryRecovery[]> {
  if (!existsSync(mailboxDir)) return [];
  const result: DeliveryRecovery[] = [];
  for (const member of await readdir(mailboxDir)) {
    const memberDir = join(mailboxDir, member);
    if (!existsSync(memberDir)) continue;
    for (const entry of await readdir(memberDir)) {
      if (!entry.startsWith(".delivering-") || !entry.endsWith(".json")) continue;
      const uuid = entry.slice(".delivering-".length, -".json".length);
      const full = join(memberDir, entry);
      const { mtimeMs } = await stat(full);
      if (now - mtimeMs < ttlMs) continue;
      const target = join(memberDir, `${uuid}.json`);
      // link = 原子 create-if-not-exists：待读位已被占（processed 防线命中）
      // 时 EEXIST，残片丢弃；绝不用 rename（会静默覆盖待读位）。
      try {
        await link(full, target);
        await rm(full);
        result.push({ member, uuid, action: "requeued" });
      } catch (error) {
        if ((error as NodeJS.ErrnoException).code === "EEXIST") {
          await rm(full);
          result.push({ member, uuid, action: "dropped" });
        } else {
          throw error;
        }
      }
    }
  }
  return result;
}

export interface SentinelRecovery {
  role: string;
  action: "discarded";
}

/**
 * 黑板 running 哨兵处理：state/<role>.json 含 `"status":"running"` 的分片
 * 整体作废重做（unlink 整文件——半新半旧的脏黑板不可复用）。
 */
export async function discardRunningSentinels(stateDir: string): Promise<SentinelRecovery[]> {
  if (!existsSync(stateDir)) return [];
  const result: SentinelRecovery[] = [];
  for (const entry of await readdir(stateDir)) {
    if (!entry.endsWith(".json")) continue;
    const full = join(stateDir, entry);
    const shard = await readJson<{ status?: string }>(full);
    if (shard?.status !== "running") continue;
    await rm(full);
    result.push({ role: entry.replace(/\.json$/, ""), action: "discarded" });
  }
  return result;
}

